<?php
if(!defined('ABSPATH')){exit;}
final class SPF_Data_Tools {
 public function hooks(){add_action('admin_post_spf_load_demo_data',[$this,'load_demo']);add_action('admin_post_spf_reset_operational_data',[$this,'reset']);}
 private function authorize(){if(!current_user_can(SPF_Roles::SETTINGS)&&!current_user_can('manage_options')){wp_die(esc_html__('No tienes permisos para usar estas herramientas.','sistema-para-farmacias'));}}
 private function redirect($notice,$type='success'){wp_safe_redirect(add_query_arg(['page'=>'spf-settings','spf_tool_notice'=>$notice,'spf_tool_notice_type'=>$type],admin_url('admin.php')));exit;}
 public static function reset_operational_data(){global $wpdb;$tables=['invoices','sale_items','sales','stock_movements','lots','customers','products'];foreach($tables as $name){$table=SPF_Database::table($name);$result=$wpdb->query("TRUNCATE TABLE `$table`");if($result===false){return new WP_Error('spf_reset_failed',sprintf(__('No se pudo vaciar la tabla %s.','sistema-para-farmacias'),$name));}}update_option('spf_demo_data_loaded','0');update_option('spf_last_reset_at',current_time('mysql'));return true;}
 public function reset(){ $this->authorize();check_admin_referer('spf_reset_operational_data');$confirm=strtoupper(trim(sanitize_text_field(wp_unslash($_POST['confirm_word']??''))));if($confirm!=='RESET'){$this->redirect('reset_confirmation','error');}$result=self::reset_operational_data();if(is_wp_error($result)){$this->redirect('reset_failed','error');}$this->redirect('reset_ok'); }
 public function load_demo(){ $this->authorize();check_admin_referer('spf_load_demo_data');$confirm=strtoupper(trim(sanitize_text_field(wp_unslash($_POST['confirm_word']??''))));if($confirm!=='DEMO'){$this->redirect('demo_confirmation','error');}$reset=self::reset_operational_data();if(is_wp_error($reset)){$this->redirect('demo_failed','error');}$result=self::seed_demo_data();if(is_wp_error($result)){$this->redirect('demo_failed','error');}$this->redirect('demo_ok'); }
 private static function seed_demo_data(){global $wpdb;$products=SPF_Database::table('products');$lots=SPF_Database::table('lots');$movements=SPF_Database::table('stock_movements');$customers=SPF_Database::table('customers');$sales=SPF_Database::table('sales');$sale_items=SPF_Database::table('sale_items');$now=current_time('mysql');$user_id=get_current_user_id();$tax_type=SPF_Tax::default_class();$clock=new DateTimeImmutable('now',wp_timezone());$demo_products=[
  ['barcode'=>'100000000001','name'=>__('Paracetamol 500 mg','sistema-para-farmacias'),'active'=>__('Paracetamol','sistema-para-farmacias'),'category'=>__('Analgésicos','sistema-para-farmacias'),'buy'=>0.80,'sell'=>2.50,'min'=>10,'unit'=>__('caja','sistema-para-farmacias'),'lot'=>'DEMO-L001','months'=>18,'qty'=>60],
  ['barcode'=>'100000000002','name'=>__('Ibuprofeno 400 mg','sistema-para-farmacias'),'active'=>__('Ibuprofeno','sistema-para-farmacias'),'category'=>__('Antiinflamatorios','sistema-para-farmacias'),'buy'=>1.10,'sell'=>3.50,'min'=>12,'unit'=>__('caja','sistema-para-farmacias'),'lot'=>'DEMO-L002','months'=>14,'qty'=>45],
  ['barcode'=>'100000000003','name'=>__('Omeprazol 20 mg','sistema-para-farmacias'),'active'=>__('Omeprazol','sistema-para-farmacias'),'category'=>__('Digestivo','sistema-para-farmacias'),'buy'=>0.90,'sell'=>3.00,'min'=>15,'unit'=>__('caja','sistema-para-farmacias'),'lot'=>'DEMO-L003','months'=>10,'qty'=>35],
  ['barcode'=>'100000000004','name'=>__('Alcohol 70% 120 ml','sistema-para-farmacias'),'active'=>__('Alcohol etílico','sistema-para-farmacias'),'category'=>__('Primeros auxilios','sistema-para-farmacias'),'buy'=>2.20,'sell'=>5.00,'min'=>8,'unit'=>__('frasco','sistema-para-farmacias'),'lot'=>'DEMO-L004','months'=>24,'qty'=>25],
  ['barcode'=>'100000000005','name'=>__('Amoxicilina 500 mg','sistema-para-farmacias'),'active'=>__('Amoxicilina','sistema-para-farmacias'),'category'=>__('Antibióticos','sistema-para-farmacias'),'buy'=>4.50,'sell'=>9.90,'min'=>10,'unit'=>__('caja','sistema-para-farmacias'),'lot'=>'DEMO-L005','months'=>8,'qty'=>18],
  ['barcode'=>'100000000006','name'=>__('Sales de rehidratación oral','sistema-para-farmacias'),'active'=>__('Sales de rehidratación','sistema-para-farmacias'),'category'=>__('Hidratación','sistema-para-farmacias'),'buy'=>1.50,'sell'=>4.00,'min'=>6,'unit'=>__('sobre','sistema-para-farmacias'),'lot'=>'DEMO-L006','months'=>5,'qty'=>30],
 ];$ids=[];$by_id=[];foreach($demo_products as $item){$ok=$wpdb->insert($products,['barcode'=>$item['barcode'],'name'=>$item['name'],'active_ingredient'=>$item['active'],'laboratory'=>__('Laboratorio Demo','sistema-para-farmacias'),'category'=>$item['category'],'purchase_price'=>$item['buy'],'sale_price'=>$item['sell'],'tax_type'=>$tax_type,'stock_min'=>$item['min'],'unit'=>$item['unit'],'status'=>'active','created_at'=>$now,'updated_at'=>$now]);if(!$ok){return new WP_Error('spf_demo_product',__('No se pudo crear un producto de prueba.','sistema-para-farmacias'));}$pid=(int)$wpdb->insert_id;$ids[$item['barcode']]=$pid;$by_id[$pid]=$item;$expiry=$clock->modify('+'.$item['months'].' months')->format('Y-m-d');$wpdb->insert($lots,['product_id'=>$pid,'lot_number'=>$item['lot'],'expiry_date'=>$expiry,'quantity'=>$item['qty'],'purchase_price'=>$item['buy'],'supplier'=>__('Proveedor Demo','sistema-para-farmacias'),'created_at'=>$now,'updated_at'=>$now]);$lot_id=(int)$wpdb->insert_id;$wpdb->insert($movements,['product_id'=>$pid,'lot_id'=>$lot_id,'movement_type'=>'purchase','quantity'=>$item['qty'],'previous_stock'=>0,'new_stock'=>$item['qty'],'reason'=>__('Carga de datos de prueba','sistema-para-farmacias'),'user_id'=>$user_id,'created_at'=>$now]);}
  $person=SPF_Config::person_documents();$business=SPF_Config::business_documents();$doc_type=(string)array_key_first($person?:$business?:['GENERIC'=>__('Documento','sistema-para-farmacias')]);$wpdb->insert($customers,['document_type'=>$doc_type,'document_number'=>'DEMO-0001','name'=>__('Cliente Demo','sistema-para-farmacias'),'business_name'=>'','address'=>__('Dirección de prueba','sistema-para-farmacias'),'email'=>'demo@example.com','phone'=>'000000000','created_at'=>$now,'updated_at'=>$now]);$customer_id=(int)$wpdb->insert_id;$doc_keys=array_keys(SPF_Config::sales_documents());if(!$doc_keys){$doc_keys=['sale'];}$payment_keys=array_keys(SPF_Config::payment_methods());if(!$payment_keys){$payment_keys=['cash'];}$demo_sales=[['days'=>-6,'items'=>[['barcode'=>'100000000001','qty'=>2],['barcode'=>'100000000004','qty'=>1]]],['days'=>-4,'items'=>[['barcode'=>'100000000002','qty'=>1],['barcode'=>'100000000003','qty'=>2]]],['days'=>-2,'items'=>[['barcode'=>'100000000005','qty'=>1]]],['days'=>0,'items'=>[['barcode'=>'100000000001','qty'=>3],['barcode'=>'100000000006','qty'=>2]]]];
  foreach($demo_sales as $index=>$demo){$sale_time=$clock->modify(($demo['days']>=0?'+':'').$demo['days'].' days')->modify('+'.($index*30).' minutes')->format('Y-m-d H:i:s');$subtotal=0.0;$tax_total=0.0;$total=0.0;$prepared=[];foreach($demo['items'] as $line){$pid=$ids[$line['barcode']];$product=$by_id[$pid];$qty=(int)$line['qty'];$tax=SPF_Tax::calculate_from_total($product['sell']*$qty,$tax_type);$subtotal+=$tax['subtotal'];$tax_total+=$tax['tax'];$total+=$tax['total'];$prepared[]=['product_id'=>$pid,'product'=>$product,'qty'=>$qty,'tax'=>$tax];}$sale_number='DEMO-'.$clock->modify(($demo['days']>=0?'+':'').$demo['days'].' days')->format('Ymd').'-'.($index+1);$document_type=$doc_keys[$index%count($doc_keys)];$payment=$payment_keys[$index%count($payment_keys)];$wpdb->insert($sales,['sale_number'=>$sale_number,'customer_id'=>$customer_id,'document_type'=>$document_type,'payment_method'=>$payment,'subtotal'=>round($subtotal,2),'igv'=>round($tax_total,2),'total'=>round($total,2),'status'=>'completed','user_id'=>$user_id,'created_at'=>$sale_time,'updated_at'=>$sale_time]);$sale_id=(int)$wpdb->insert_id;if(!$sale_id){return new WP_Error('spf_demo_sale',__('No se pudo crear una venta de prueba.','sistema-para-farmacias'));}foreach($prepared as $line){$lot=$wpdb->get_row($wpdb->prepare("SELECT * FROM $lots WHERE product_id=%d AND quantity>0 ORDER BY expiry_date ASC,id ASC LIMIT 1",$line['product_id']),ARRAY_A);$lot_id=$lot?(int)$lot['id']:null;$previous=$lot?(int)$lot['quantity']:0;$new=max(0,$previous-$line['qty']);if($lot_id){$wpdb->update($lots,['quantity'=>$new,'updated_at'=>$sale_time],['id'=>$lot_id]);}$wpdb->insert($sale_items,['sale_id'=>$sale_id,'product_id'=>$line['product_id'],'lot_id'=>$lot_id,'product_name'=>$line['product']['name'],'quantity'=>$line['qty'],'unit_price'=>$line['product']['sell'],'subtotal'=>$line['tax']['subtotal'],'igv'=>$line['tax']['tax'],'total'=>$line['tax']['total'],'tax_type'=>$tax_type]);$wpdb->insert($movements,['product_id'=>$line['product_id'],'lot_id'=>$lot_id,'movement_type'=>'sale','quantity'=>-$line['qty'],'previous_stock'=>$previous,'new_stock'=>$new,'reason'=>__('Venta de prueba','sistema-para-farmacias').' '.$sale_number,'user_id'=>$user_id,'created_at'=>$sale_time]);}SPF_Documents::create_for_sale($sale_id,$document_type,$sale_number,$total,$customer_id);}
  update_option('spf_demo_data_loaded','1');update_option('spf_demo_data_loaded_at',current_time('mysql'));return true;
 }
}
